-- Registres additifs : aucune reprise implicite de documents ou décision.
CREATE TABLE governance_items (id TEXT PRIMARY KEY, condominium_id TEXT NOT NULL REFERENCES condominiums(id), kind TEXT NOT NULL CHECK(kind IN ('meeting','requirement','decision','action','offer','charge_key')), dossier_year INTEGER NOT NULL CHECK(dossier_year BETWEEN 1900 AND 2200), parent_id TEXT REFERENCES governance_items(id), title TEXT NOT NULL, audience TEXT NOT NULL CHECK(audience IN ('owners','council','management')), payload TEXT NOT NULL CHECK(json_valid(payload)), version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), updated_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX governance_context ON governance_items(condominium_id,dossier_year,kind);
CREATE INDEX governance_parent ON governance_items(parent_id,kind);
CREATE TRIGGER governance_created AFTER INSERT ON governance_items BEGIN INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'governance_created',NEW.id,NEW.version,NEW.updated_at); END;
CREATE TRIGGER governance_updated AFTER UPDATE ON governance_items BEGIN INSERT INTO item_revisions(resource_id,condominium_id,actor_id,version,snapshot,happened_at) VALUES(OLD.id,OLD.condominium_id,NEW.updated_by,OLD.version,json_object('kind',OLD.kind,'title',OLD.title,'audience',OLD.audience,'dossierYear',OLD.dossier_year,'parentId',OLD.parent_id,'payload',json(OLD.payload)),NEW.updated_at); INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'governance_updated',NEW.id,NEW.version,NEW.updated_at); END;
-- Recheck mutable parent decisions inside the same SQLite write transaction.
CREATE TRIGGER governance_execution_insert BEFORE INSERT ON governance_items WHEN (NEW.kind='action' AND json_extract(NEW.payload,'$.actionType')='execution' AND json_extract(NEW.payload,'$.status') IN ('in_progress','waiting','done')) OR (NEW.kind='offer' AND json_extract(NEW.payload,'$.status')='signed') BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM governance_items p WHERE p.id=NEW.parent_id AND p.condominium_id=NEW.condominium_id AND p.kind='decision' AND json_extract(p.payload,'$.status')='adopted') THEN RAISE(ABORT,'governance_parent_changed') END; END;
CREATE TRIGGER governance_execution_update BEFORE UPDATE ON governance_items WHEN (NEW.kind='action' AND json_extract(NEW.payload,'$.actionType')='execution' AND json_extract(NEW.payload,'$.status') IN ('in_progress','waiting','done')) OR (NEW.kind='offer' AND json_extract(NEW.payload,'$.status')='signed') BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM governance_items p WHERE p.id=NEW.parent_id AND p.condominium_id=NEW.condominium_id AND p.kind='decision' AND json_extract(p.payload,'$.status')='adopted') THEN RAISE(ABORT,'governance_parent_changed') END; END;
CREATE TRIGGER governance_result_guard BEFORE UPDATE ON governance_items WHEN OLD.kind='decision' AND json_extract(OLD.payload,'$.status')='adopted' AND json_extract(NEW.payload,'$.status')!='adopted' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM governance_items c WHERE c.parent_id=OLD.id AND ((c.kind='action' AND json_extract(c.payload,'$.actionType')='execution' AND json_extract(c.payload,'$.status') IN ('in_progress','waiting','done')) OR (c.kind='offer' AND json_extract(c.payload,'$.status')='signed'))) THEN RAISE(ABORT,'governance_parent_changed') END; END;
